import { Component, OnInit } from '@angular/core';
import { jobSeeker } from 'src/app/auth/Models/jobSeeker';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';

/**
 * Row shape used by the admin job-seekers table. The backend's jobSeeker model
 * doesn't carry status / joined date / application count, so the admin view
 * keeps a slightly richer shape locally. We `Omit` password because the admin
 * list should never carry credentials.
 */
type AdminSeekerRow = Omit<jobSeeker, 'password' | 'resumeUrl'> & {
  id: number;
  joined: string;
  applications: number;
  status: 'ACTIVE' | 'SUSPENDED' | 'REPORTED';
};

@Component({
  selector: 'app-admin-jobseekers',
  templateUrl: './admin-jobseekers.component.html',
  styleUrls: ['./admin-jobseekers.component.css']
})
export class AdminJobseekersComponent implements OnInit {

  seekers: AdminSeekerRow[] = [];
  totalSeekers = 0;
  activeSeekers = 0;
  dormantSeekers = 0;
  suspendedSeekers = 0;

  searchTerm = '';
  selectedLocation = 'All locations';

  selected: Set<number> = new Set();

  private readonly seedRows: AdminSeekerRow[] = [
    { id: 1, firstName: 'Aditi',   lastName: 'Menon',  email: 'aditi.menon@email.com',  skills: [], location: 'Kochi',     joined: 'Feb 2024', applications: 14, status: 'ACTIVE' },
    { id: 2, firstName: 'Rohan',   lastName: 'Iyer',   email: 'rohan.iyer@email.com',   skills: [], location: 'Bengaluru', joined: 'May 2024', applications: 6,  status: 'ACTIVE' },
    { id: 3, firstName: 'Meera',   lastName: 'Nair',   email: 'meera.nair@email.com',   skills: [], location: 'Chennai',   joined: 'Aug 2023', applications: 22, status: 'ACTIVE' },
    { id: 4, firstName: 'Sam',     lastName: 'Thomas', email: 'sam.thomas@email.com',   skills: [], location: 'Hyderabad', joined: 'Mar 2025', applications: 9,  status: 'ACTIVE' },
    { id: 5, firstName: 'Priya',   lastName: 'Das',    email: 'priya.das@email.com',    skills: [], location: 'Pune',      joined: 'Jun 2024', applications: 3,  status: 'SUSPENDED' },
    { id: 6, firstName: 'Vikram',  lastName: 'Rao',    email: 'vikram.rao@email.com',   skills: [], location: 'Mumbai',    joined: 'Jan 2026', applications: 11, status: 'ACTIVE' },
    { id: 7, firstName: 'Anjali',  lastName: 'Pillai', email: 'anjali.pillai@email.com',skills: [], location: 'Remote',    joined: 'Oct 2023', applications: 18, status: 'REPORTED' },
    { id: 8, firstName: 'Karthik', lastName: 'Bhat',   email: 'karthik.bhat@email.com', skills: [], location: 'Kochi',     joined: 'Nov 2024', applications: 5,  status: 'ACTIVE' }
  ];

  constructor(private jobseekerService: JobseekerService) {}

  ngOnInit(): void {
    this.load();
  }

  private load(): void {
    this.jobseekerService.getAllJobSeekers().subscribe({
      next: (list) => {
        this.seekers = (list || []).map((s, i) => ({
          ...s,
          id: i + 1,
          joined: '2024',
          applications: 0,
          status: 'ACTIVE'
        }));
        if (this.seekers.length === 0) {
          this.seekers = this.seedRows;
        }
        this.recomputeCounts();
      },
      error: () => {
        this.seekers = this.seedRows;
        this.recomputeCounts();
      }
    });
  }

  private recomputeCounts(): void {
    this.totalSeekers = this.seekers.length;
    this.activeSeekers = this.seekers.filter(s => s.status === 'ACTIVE').length;
    this.suspendedSeekers = this.seekers.filter(s => s.status === 'SUSPENDED').length;
    this.dormantSeekers = Math.max(0, this.totalSeekers - this.activeSeekers - this.suspendedSeekers);
  }

  toggle(id: number): void {
    this.selected.has(id) ? this.selected.delete(id) : this.selected.add(id);
  }

  toggleAll(event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    if (checked) {
      this.filteredRows.forEach(r => this.selected.add(r.id));
    } else {
      this.selected.clear();
    }
  }

  suspend(row: AdminSeekerRow): void {
    row.status = 'SUSPENDED';
    this.recomputeCounts();
  }

  reinstate(row: AdminSeekerRow): void {
    row.status = 'ACTIVE';
    this.recomputeCounts();
  }

  resolveReport(row: AdminSeekerRow): void {
    row.status = 'ACTIVE';
    this.recomputeCounts();
  }

  deleteRow(row: AdminSeekerRow): void {
    this.seekers = this.seekers.filter(s => s.id !== row.id);
    this.selected.delete(row.id);
    this.recomputeCounts();
  }

  bulkSuspend(): void {
    this.seekers.forEach(s => {
      if (this.selected.has(s.id) && s.status === 'ACTIVE') {
        s.status = 'SUSPENDED';
      }
    });
    this.recomputeCounts();
  }

  bulkDelete(): void {
    this.seekers = this.seekers.filter(s => !this.selected.has(s.id));
    this.selected.clear();
    this.recomputeCounts();
  }

  bulkEmail(): void {
    // Email is wired through a backend; this is a UI-only placeholder.
    alert(`Email queued for ${this.selected.size} seekers.`);
    this.selected.clear();
  }

  get filteredRows(): AdminSeekerRow[] {
    const term = this.searchTerm.trim().toLowerCase();
    return this.seekers.filter(s => {
      const matchesTerm = !term
        || `${s.firstName} ${s.lastName}`.toLowerCase().includes(term)
        || (s.email || '').toLowerCase().includes(term);
      const matchesLocation = this.selectedLocation === 'All locations' || s.location === this.selectedLocation;
      return matchesTerm && matchesLocation;
    });
  }
}
<div class="page">
<app-header variant="admin"></app-header>
<div class="app-shell">
<app-sidebar variant="admin"></app-sidebar>
<main class="main-wide">

<div class="page-title">Job Seekers</div>
<div class="page-sub">Manage candidate accounts, review activity, and resolve support tickets.</div>

<div class="card-row-3" style="margin-bottom:24px;">
  <div class="stat-card"><div class="n">{{ totalSeekers | number }}</div><div class="l">Total seekers</div></div>
  <div class="stat-card"><div class="n">{{ activeSeekers | number }}</div><div class="l">Active</div><span class="sub">logged in 30d</span></div>
  <div class="stat-card"><div class="n">{{ dormantSeekers | number }}</div><div class="l">Dormant</div><span class="sub">90d+ inactive</span></div>
</div>
<div class="card-row-3" style="margin-bottom:32px;grid-template-columns:1fr 1fr 1fr;max-width:720px;">
  <div class="stat-card"><div class="n">142</div><div class="l">New this week</div></div>
  <div class="stat-card"><div class="n">{{ suspendedSeekers }}</div><div class="l">Suspended</div></div>
  <div class="stat-card"><div class="n">3</div><div class="l">Open reports</div></div>
</div>

<div class="tab-row">
  <span class="tab active">All ({{ totalSeekers }})</span>
  <span class="tab">Active ({{ activeSeekers }})</span>
  <span class="tab">Suspended ({{ suspendedSeekers }})</span>
  <span class="tab">Reported (3)</span>
</div>

<div class="section-head" style="margin-top:16px;">
  <h2>Job seeker directory</h2>
  <div style="display:flex;gap:10px;align-items:center;">
    <select [(ngModel)]="selectedLocation" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;background:var(--paper);">
      <option>All locations</option>
      <option>Kochi</option>
      <option>Bengaluru</option>
      <option>Chennai</option>
      <option>Hyderabad</option>
      <option>Mumbai</option>
      <option>Pune</option>
      <option>Remote</option>
    </select>
    <input type="text" [(ngModel)]="searchTerm" placeholder="Search by name or email" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;width:240px;">
  </div>
</div>

<div class="table-wrap">
  <table>
    <thead>
      <tr>
        <th><input type="checkbox" (change)="toggleAll($event)"></th>
        <th>Name</th>
        <th>Email</th>
        <th>Location</th>
        <th>Joined</th>
        <th>Applications</th>
        <th>Status</th>
        <th></th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let s of filteredRows">
        <td><input type="checkbox" [checked]="selected.has(s.id)" (change)="toggle(s.id)"></td>
        <td>{{ s.firstName }} {{ s.lastName }}</td>
        <td>{{ s.email }}</td>
        <td>{{ s.location }}</td>
        <td>{{ s.joined }}</td>
        <td>{{ s.applications }}</td>
        <td>
          <span class="chip"
                [ngClass]="{
                  'chip-approved': s.status === 'ACTIVE',
                  'chip-rejected': s.status === 'SUSPENDED',
                  'chip-pending': s.status === 'REPORTED'
                }">{{ s.status }}</span>
        </td>
        <td class="actions">
          <a [routerLink]="['/admin/jobseekers', s.id]">View</a>
          <a *ngIf="s.status === 'ACTIVE'"   href="javascript:void(0)" (click)="suspend(s)">Suspend</a>
          <a *ngIf="s.status === 'SUSPENDED'" href="javascript:void(0)" (click)="reinstate(s)">Reinstate</a>
          <a *ngIf="s.status === 'REPORTED'" href="javascript:void(0)" (click)="resolveReport(s)">Resolve</a>
          <a href="javascript:void(0)" class="danger" (click)="deleteRow(s)">Delete</a>
        </td>
      </tr>
      <tr *ngIf="filteredRows.length === 0">
        <td colspan="8" class="muted" style="text-align:center;padding:24px;">No seekers match your filters.</td>
      </tr>
    </tbody>
  </table>
</div>

<div style="display:flex;justify-content:space-between;align-items:center;margin-top:20px;font-size:13px;color:var(--muted);">
  <div>Showing {{ filteredRows.length }} of {{ totalSeekers }}</div>
  <div style="display:flex;gap:8px;align-items:center;">
    <button class="btn btn-secondary btn-sm">Previous</button>
    <span>Page 1</span>
    <button class="btn btn-secondary btn-sm">Next</button>
  </div>
</div>

<div class="card" style="margin-top:32px;">
  <h3 style="font-size:14px;margin-bottom:12px;">Bulk actions</h3>
  <p class="muted" style="font-size:13px;margin-bottom:12px;">
    {{ selected.size }} selected. Apply moderation actions to multiple accounts at once.
  </p>
  <div style="display:flex;gap:10px;">
    <button class="btn btn-secondary btn-sm" (click)="bulkEmail()">Email selected</button>
    <button class="btn btn-secondary btn-sm" (click)="bulkSuspend()">Suspend selected</button>
    <button class="btn btn-outline-danger btn-sm" (click)="bulkDelete()">Delete selected</button>
  </div>
</div>

</main>
</div>
</div>
